using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using GenesisMesh;
using NSec.Cryptography;
using Xunit;

namespace GenesisMesh.Sdk.Tests;

/// <summary>
/// Shared conformance suite <c>audit</c> (v1.5.0), generated by the Python reference
/// (genesismesh/conformance/generate_vectors.py audit) and copied here unchanged. This SDK runs the vectors of what
/// it verifies: the signed forms of the new records, the NA key history, the keys valid at a time, the time a record
/// read alone is placed at, and decisions judged with a history. Audit packs (and their report cells, ranges and
/// changes files), evidence exports, registry keys, anchors and the completeness check are verified by the core and
/// genesis-mesh-verify. Then decisions and agreements signed before and after a succession built here.
/// </summary>
public class KeyHistoryTests
{
    private static readonly string SuitePath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "audit.json");
    private static readonly string InteropPath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "interop.json");
    private static readonly HashSet<string> KindsRun = new()
    {
        "canonical_form", "key_history", "key_at", "decision_at_record_time", "record_time",
    };
    private static readonly HashSet<string> KindsNotRun = new()
    {
        "pack", "verify_export", "verify_range", "verify_anchors", "completeness", "registry_keys", "report_cell", "changes_file",
    };

    private static JsonElement.ArrayEnumerator Vectors() =>
        JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement.GetProperty("vectors").EnumerateArray();

    private static JsonElement Vector(string id) => Vectors().Single(v => v.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Vectors()
        .Where(v => !KindsNotRun.Contains(v.GetProperty("kind").GetString()!))
        .Select(v => new object[] { v.GetProperty("id").GetString()! });

    private static NAKeyHistory HistoryOf(JsonElement input)
    {
        var r = OfflineVerifier.VerifyKeyHistory(input.GetProperty("genesis").GetRawText(),
            input.GetProperty("successions").GetRawText(), input.GetProperty("root_public_key").GetString()!);
        Assert.True(r.Verified, r.Reason);
        return r.History!;
    }

    private static string Utc(DateTimeOffset t) => t.UtcDateTime.ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture);

    private static string? Iso(DateTimeOffset? t) => t is { } v ? Utc(v) : null;

    private static List<Dictionary<string, object?>> KeyDicts(NAKeyHistory? history) => (history?.Keys ?? Array.Empty<NAKey>()).Select(k =>
        new Dictionary<string, object?>
        {
            ["key_sequence"] = k.KeySequence,
            ["key_id"] = k.KeyId,
            ["public_key"] = k.PublicKey,
            ["valid_from"] = Iso(k.ValidFrom),
            ["succeeded_at"] = Iso(k.SucceededAt),
            ["valid_to"] = Iso(k.ValidTo),
            ["valid_to_enforced"] = k.ValidToEnforced,
        }).ToList();

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "audit", typeof(KeyHistoryTests), nameof(ReproducesTheReferenceOutcome), VectorIds(), KindsRun, KindsNotRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceOutcome(string id)
    {
        var v = Vector(id);
        object got;
        switch (v.GetProperty("kind").GetString())
        {
            case "canonical_form":
                {
                    var body = OfflineVerifier.ReceivedCanonical(v.GetProperty("model").GetString()!, v.GetProperty("record"));
                    got = new Dictionary<string, object>
                    {
                        ["canonical"] = body,
                        ["digest"] = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(body))).ToLowerInvariant(),
                    };
                    break;
                }
            case "key_history":
                {
                    var input = v.GetProperty("input");
                    var r = OfflineVerifier.VerifyKeyHistory(input.GetProperty("genesis").GetRawText(),
                        input.GetProperty("successions").GetRawText(), input.GetProperty("root_public_key").GetString()!);
                    got = new Dictionary<string, object>
                    {
                        ["verified"] = r.Verified,
                        ["failures"] = r.Verified ? new List<object>()
                            : new List<object> { new Dictionary<string, object?> { ["key_sequence"] = r.KeySequence, ["reason"] = r.Reason } },
                        ["keys"] = KeyDicts(r.History),
                    };
                    break;
                }
            case "key_at":
                {
                    var input = v.GetProperty("input");
                    got = new Dictionary<string, object>
                    {
                        ["keys"] = HistoryOf(input).KeysAt(OfflineVerifier.ParseTimestamp(input.GetProperty("at").GetString()!)),
                    };
                    break;
                }
            case "decision_at_record_time":
                {
                    var input = v.GetProperty("input");
                    var history = HistoryOf(input);
                    var decision = input.GetProperty("decision").GetRawText();
                    got = new Dictionary<string, object>
                    {
                        ["at_record_time"] = OfflineVerifier.VerifyBoundaryDecision(decision,
                            new DecisionVerifyOptions { KeyHistory = history, AtRecordTime = true }).Reason,
                        ["now"] = OfflineVerifier.VerifyBoundaryDecision(decision, new DecisionVerifyOptions
                        {
                            KeyHistory = history,
                            Now = OfflineVerifier.ParseTimestamp(input.GetProperty("now").GetString()!),
                        }).Reason,
                    };
                    break;
                }
            case "record_time":
                got = new Dictionary<string, object?>
                {
                    ["field"] = NAKeyHistory.RecordTimeFields.TryGetValue(v.GetProperty("model").GetString()!, out var f) ? f : null,
                };
                break;
            default:
                throw new InvalidOperationException($"vector kind {v.GetProperty("kind").GetString()} is not run");
        }
        Assert.Equal(Canonical.FromJson(v.GetProperty("expected").GetRawText()), Canonical.FromJson(JsonSerializer.Serialize(got)));
    }

    // ── a succession built and signed here ─────────────────────────────────

    private static Key Seeded(byte b) =>
        Key.Import(SignatureAlgorithm.Ed25519, Enumerable.Repeat(b, 32).ToArray(), KeyBlobFormat.RawPrivateKey);

    private static string Pub(Key k) => Convert.ToBase64String(k.PublicKey.Export(KeyBlobFormat.RawPublicKey));

    /// <summary>The record with its signatures set: one by each signer over its received form.</summary>
    private static JsonObject SignedWith(string model, JsonObject record, params (string KeyId, Key Key)[] signers)
    {
        using var doc = JsonDocument.Parse(record.ToJsonString());
        var body = Encoding.UTF8.GetBytes(OfflineVerifier.ReceivedCanonical(model, doc.RootElement));
        var sigs = new JsonArray();
        foreach (var (keyId, key) in signers)
            sigs.Add(new JsonObject { ["key_id"] = keyId, ["sig"] = Convert.ToBase64String(SignatureAlgorithm.Ed25519.Sign(key, body)) });
        record["signatures"] = sigs;
        return record;
    }

    /// <summary>A genesis block in the form the reference writes, signed by the root key.</summary>
    private static JsonObject Genesis(string sovereign, Key root, Key na) => SignedWith("GenesisBlock", new JsonObject
    {
        ["network_name"] = sovereign,
        ["network_version"] = "v1",
        ["root_public_key"] = Pub(root),
        ["network_authority"] = new JsonObject
        {
            ["public_key"] = Pub(na),
            ["valid_from"] = "2026-01-01T00:00:00Z",
            ["valid_to"] = "2026-04-01T00:00:00Z",
        },
        ["allowed_crypto_suites"] = new JsonArray("ed25519", "x25519"),
        ["allowed_transports"] = new JsonArray("quic", "wireguard"),
        ["policy_manifest"] = new JsonObject { ["hash"] = "sha256:test", ["url"] = null },
        ["bootstrap_anchors"] = new JsonArray(),
    }, ("root", root));

    /// <summary>
    /// The first succession, previous to next at effective, with its three signatures: the root key's, the new key's
    /// and the outgoing key's.
    /// </summary>
    private static JsonObject Succession(string sovereign, Key root, Key previous, Key next, DateTimeOffset effective) =>
        SignedWith("KeySuccessionRecord", new JsonObject
        {
            ["succession_id"] = "00000000-0000-4000-8000-000000000001",
            ["sovereign_id"] = sovereign,
            ["key_sequence"] = 2,
            ["previous_key_id"] = "na-1",
            ["previous_public_key"] = Pub(previous),
            ["new_key_id"] = "na-2",
            ["new_public_key"] = Pub(next),
            ["effective_at"] = Utc(effective),
            ["new_valid_to"] = Utc(effective.AddYears(2)),
            ["issued_at"] = Utc(effective.AddDays(-9)),
        }, ("root", root), ("na-2", next), ("na-1", previous));

    private static readonly DateTimeOffset Effective = new(2026, 3, 1, 0, 0, 0, TimeSpan.Zero);

    private sealed class World : IDisposable
    {
        public Key Root { get; } = Seeded(0x71);
        public Key Na1 { get; } = Seeded(0x72);
        public Key Na2 { get; } = Seeded(0x73);
        public string GenesisJson { get; }
        public string SuccessionsJson { get; }
        public NAKeyHistory History { get; }

        public World()
        {
            GenesisJson = Genesis("sovereign-s", Root, Na1).ToJsonString();
            SuccessionsJson = new JsonArray(Succession("sovereign-s", Root, Na1, Na2, Effective)).ToJsonString();
            var r = OfflineVerifier.VerifyKeyHistory(GenesisJson, SuccessionsJson, Pub(Root));
            Assert.True(r.Verified, r.Reason);
            History = r.History!;
        }

        public JsonObject FirstSuccession() => JsonNode.Parse(SuccessionsJson)!.AsArray()[0]!.AsObject();

        public void Dispose()
        {
            Root.Dispose();
            Na1.Dispose();
            Na2.Dispose();
        }
    }

    /// <summary>The audit suite's decision, made at <paramref name="madeAt"/>, valid for a lifetime, signed by a key.</summary>
    private static string DecisionAt(DateTimeOffset madeAt, TimeSpan lifetime, Key key)
    {
        var decision = JsonNode.Parse(Vector("decision-at-record-time").GetProperty("input").GetProperty("decision").GetRawText())!.AsObject();
        decision["decision_made_at"] = Utc(madeAt);
        decision["decision_valid_until"] = Utc(madeAt + lifetime);
        using var doc = JsonDocument.Parse(decision.ToJsonString());
        var body = Canonical.Of(doc.RootElement, new[] { "signature" }, OfflineVerifier.DecisionOmittedWhenAbsent);
        decision["signature"] = new JsonObject
        {
            ["key_id"] = "k",
            ["sig"] = Convert.ToBase64String(SignatureAlgorithm.Ed25519.Sign(key, Encoding.UTF8.GetBytes(body))),
        };
        return decision.ToJsonString();
    }

    public static IEnumerable<object[]> SuccessionCases() => new[]
    {
        new object[] { "old key before the succession", -3600, 300, 1, "authorized" },
        new object[] { "new key before the succession", -3600, 300, 2, "na_key_not_valid_at_time" },
        new object[] { "new key when it takes effect", 0, 300, 2, "authorized" },
        new object[] { "old key during the hand-over", 299, 300, 1, "authorized" },
        new object[] { "old key at the end of the hand-over", 300, 300, 1, "na_key_not_valid_at_time" },
        new object[] { "old key long after", 30 * 86400, 300, 1, "na_key_not_valid_at_time" },
        new object[] { "new key long after", 30 * 86400, 300, 2, "authorized" },
        new object[] { "new key at its valid_to", 731 * 86400, 300, 2, "na_key_not_valid_at_time" },
        new object[] { "the root key", 0, 300, 0, "invalid_signature" },
        // The old key's end, the hand-over and the lifetime cap: 600 s past the succession.
        new object[] { "old key, valid up to the cap", 299, 301, 1, "authorized" },
        new object[] { "old key, valid past the cap", 299, 302, 1, "decision_outlives_key" },
        new object[] { "old key, a day long before the succession", -3600, 86400, 1, "decision_outlives_key" },
        new object[] { "new key, a day long", 3600, 86400, 2, "authorized" },
        new object[] { "new key, valid past its valid_to", 730 * 86400, 2 * 86400, 2, "decision_outlives_key" },
    };

    [Theory]
    [MemberData(nameof(SuccessionCases))]
    public void DecisionsSignedBeforeAndAfterASuccession(string name, int offsetSeconds, int lifetimeSeconds, int signer, string expected)
    {
        _ = name;
        using var w = new World();
        var madeAt = Effective.AddSeconds(offsetSeconds);
        var decision = DecisionAt(madeAt, TimeSpan.FromSeconds(lifetimeSeconds), signer switch { 1 => w.Na1, 2 => w.Na2, _ => w.Root });
        Assert.Equal(expected, OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { KeyHistory = w.History, Now = madeAt.AddMinutes(1) }).Reason);
        // Judged at its own time, years later, the same outcome.
        Assert.Equal(expected, OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { KeyHistory = w.History, AtRecordTime = true, Now = madeAt.AddYears(5) }).Reason);
    }

    [Fact]
    public void WithoutAKeyHistoryDecisionsVerifyAsBefore()
    {
        using var w = new World();
        var madeAt = Effective.AddHours(-1);
        var decision = DecisionAt(madeAt, TimeSpan.FromMinutes(5), w.Na2);
        var now = madeAt.AddMinutes(1);
        // A plain key list is valid at every time: no window, no lifetime cap, no new reason.
        Assert.Equal("authorized", OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na1), Pub(w.Na2) }, Now = now }).Reason);
        Assert.Equal("invalid_signature", OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na1) }, Now = now }).Reason);
        Assert.Equal("authorized", OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { KeyHistory = NAKeyHistory.ValidAlways(new[] { Pub(w.Na2) }), Now = now }).Reason);
        Assert.Equal("authorized", OfflineVerifier.VerifyBoundaryDecision(DecisionAt(madeAt, TimeSpan.FromDays(365), w.Na1),
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na1) }, Now = now }).Reason);
        Assert.Throws<ArgumentException>(() => OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na1) }, KeyHistory = w.History }));
        // Expired now, valid when made.
        Assert.Equal("decision_expired", OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na2) }, Now = madeAt.AddHours(1) }).Reason);
        Assert.Equal("authorized", OfflineVerifier.VerifyBoundaryDecision(decision,
            new DecisionVerifyOptions { OperatorPublicKeys = new[] { Pub(w.Na2) }, AtRecordTime = true }).Reason);
    }

    /// <summary>The interop vector generator's signing key (seeds 00..1f, 20..3f, 40..5f) for one of the public keys.</summary>
    private static Key GeneratorKey(IReadOnlyCollection<string> publicKeys)
    {
        foreach (var start in new[] { 0, 32, 64 })
        {
            var key = Key.Import(SignatureAlgorithm.Ed25519, Enumerable.Range(start, 32).Select(i => (byte)i).ToArray(),
                KeyBlobFormat.RawPrivateKey);
            if (publicKeys.Contains(Pub(key))) return key;
            key.Dispose();
        }
        throw new InvalidOperationException("no generator key for these public keys");
    }

    [Theory]
    [InlineData("before the succession", 24 * 3600 - 3600, "accepted")]
    [InlineData("during the hand-over", 24 * 3600 + 299, "accepted")]
    [InlineData("once the hand-over ends", 24 * 3600 + 300, "invalid_offerer_signature")]
    public void AgreementsArePlacedAtTheirTermsAndVouchWhileTheKeyIsAccepted(string name, int nowSeconds, string expected)
    {
        _ = name;
        var v = JsonDocument.Parse(File.ReadAllText(InteropPath)).RootElement.GetProperty("vectors").EnumerateArray()
            .Single(x => x.GetProperty("id").GetString() == "agr-001").GetProperty("input");
        var offererKeys = v.GetProperty("offerer_public_keys").EnumerateArray().Select(e => e.GetString()!).ToList();
        var responderKeys = v.GetProperty("responder_public_keys").EnumerateArray().Select(e => e.GetString()!).ToList();
        var validFrom = new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero); // agreed_terms.valid_from, signed
        using var offerer = GeneratorKey(offererKeys);
        using var root = Seeded(0x74);
        using var next = Seeded(0x75);
        NAKeyHistory HistoryWith(DateTimeOffset effective)
        {
            var r = OfflineVerifier.VerifyKeyHistory(Genesis("offerer", root, offerer).ToJsonString(),
                new JsonArray(Succession("offerer", root, offerer, next, effective)).ToJsonString(), Pub(root));
            Assert.True(r.Verified, r.Reason);
            return r.History!;
        }
        var agreement = v.GetProperty("agreement").GetRawText();
        var responder = NAKeyHistory.ValidAlways(responderKeys);
        // The offerer's agreement key is its genesis key, succeeded a day after the terms start.
        Assert.Equal(expected, OfflineVerifier.VerifyAgreementWithKeyHistory(agreement, HistoryWith(validFrom.AddDays(1)),
            responder, now: validFrom.AddSeconds(nowSeconds)).Reason);
        // Succeeded before the terms start: the key was not valid then. established_at, outside the signed form,
        // does not move the agreement.
        var moved = JsonNode.Parse(agreement)!.AsObject();
        moved["established_at"] = "2025-06-01T00:00:00Z";
        Assert.Equal("invalid_offerer_signature", OfflineVerifier.VerifyAgreementWithKeyHistory(moved.ToJsonString(),
            HistoryWith(validFrom.AddDays(-1)), responder, now: validFrom.AddDays(-2)).Reason);
        // Without a history the same agreement verifies as before.
        Assert.Equal("accepted", OfflineVerifier.VerifyAgreement(moved.ToJsonString(), offererKeys, responderKeys).Reason);
    }

    [Fact]
    public void KeyHistoryFromTheNAResponse()
    {
        using var w = new World();
        var body = new JsonObject
        {
            ["sovereign_id"] = "sovereign-s",
            ["root_public_key"] = "not trusted",
            ["handover_seconds"] = 300,
            ["genesis"] = JsonNode.Parse(w.GenesisJson),
            ["successions"] = JsonNode.Parse(w.SuccessionsJson),
            ["keys"] = new JsonArray(),
            ["signing_key_sequence"] = 2,
        }.ToJsonString();
        var r = OfflineVerifier.VerifyKeyHistoryResponse(body, Pub(w.Root));
        Assert.True(r.Verified);
        Assert.Equal(new[] { Pub(w.Na1), Pub(w.Na2) }, r.History!.AllKeys());
        // Another root key: the history proves nothing.
        var other = OfflineVerifier.VerifyKeyHistoryResponse(body, Pub(w.Na1));
        Assert.Equal(("genesis_root_mismatch", (int?)1), (other.Reason, other.KeySequence));
        Assert.Null(other.History);
        Assert.Throws<ArgumentException>(() => OfflineVerifier.VerifyKeyHistory(w.GenesisJson, w.SuccessionsJson, ""));
    }

    [Fact]
    public void SuccessionSignaturesAndForm()
    {
        using var w = new World();
        void Check(JsonObject record, string reason, int position) =>
            Assert.Equal((reason, (int?)position), Refusal(OfflineVerifier.VerifyKeyHistory(w.GenesisJson,
                new JsonArray(record.DeepClone()).ToJsonString(), Pub(w.Root))));
        static (string?, int?) Refusal(KeyHistoryVerificationResult r) => (r.Reason, r.KeySequence);
        var (root, na1, na2) = (("root", w.Root), ("na-1", w.Na1), ("na-2", w.Na2));
        const string model = "KeySuccessionRecord";
        Check(SignedWith(model, w.FirstSuccession(), root, na1), "succession_invalid_new_key_signature", 2);
        Check(SignedWith(model, w.FirstSuccession(), root, na2), "succession_invalid_previous_signature", 2);
        Check(SignedWith(model, w.FirstSuccession(), na2, na1), "succession_invalid_root_signature", 2);
        // An unknown field signed by the new key alone is still its signer's: unknown_field.
        var unknown = w.FirstSuccession();
        unknown["extra"] = "x";
        Check(SignedWith(model, unknown, na2), "unknown_field", 2);
        var backdated = w.FirstSuccession();
        backdated["issued_at"] = "2026-03-01T00:00:01Z";
        Check(SignedWith(model, backdated, root, na2, na1), "succession_backdated", 2);
        var rootAsKey = w.FirstSuccession();
        rootAsKey["new_public_key"] = Pub(w.Root);
        Check(SignedWith(model, rootAsKey, root, root, na1), "succession_key_reused", 2);
        // The reference gives a record without an id a fresh one and refuses the form.
        var noId = w.FirstSuccession();
        noId.Remove("succession_id");
        Check(SignedWith(model, noId, root, na2, na1), "non_canonical_form", 2);
        noId["key_sequence"] = 3;
        Check(noId, "invalid_signature", 3);
    }

    [Fact]
    public void TheGenesisBlockIsStrict()
    {
        using var w = new World();
        void Check(JsonObject genesis, string reason) =>
            Assert.Equal((reason, (int?)1), Refusal(OfflineVerifier.VerifyKeyHistory(genesis.ToJsonString(), null, Pub(w.Root))));
        static (string?, int?) Refusal(KeyHistoryVerificationResult r) => (r.Reason, r.KeySequence);
        var root = ("root", w.Root);
        var unknown = Genesis("sovereign-s", w.Root, w.Na1);
        unknown["extra"] = true;
        Check(unknown, "genesis_invalid_signature");
        Check(SignedWith("GenesisBlock", unknown, root), "unknown_field");
        var loose = Genesis("sovereign-s", w.Root, w.Na1);
        loose["network_authority"]!["valid_to"] = "2026-04-01T00:00:00+00:00";
        Check(SignedWith("GenesisBlock", loose, root), "non_canonical_form");
        var shortened = Genesis("sovereign-s", w.Root, w.Na1);
        shortened.Remove("bootstrap_anchors");
        Check(SignedWith("GenesisBlock", shortened, root), "non_canonical_form");
        Check(new JsonObject { ["network_name"] = "sovereign-s" }, "genesis_invalid");
    }

    [Fact]
    public void RecordTimeFieldsAreTimestamps()
    {
        using var doc = JsonDocument.Parse(StrictFields.RegistryJson);
        foreach (var (model, field) in NAKeyHistory.RecordTimeFields)
            Assert.Equal("timestamp", doc.RootElement.GetProperty("models").GetProperty(model).GetProperty("fields").GetProperty(field).GetString());
    }
}
